/**
 * Catch-all for endpoints without a hand-written mock (community, enterprise,
 * admin, backtests, …).
 *
 * `catch-all-shapes.json` maps `"METHOD /path/:param"` to an "empty but valid"
 * value generated from each API function's declared TypeScript return type
 * (arrays → [], numbers → 0, required nested objects filled in, …). Pages
 * render their empty states instead of crashing or hitting the network.
 *
 * The file is generated by a one-off scan of src/lib/api/*.ts and is safe to
 * edit by hand. To give an endpoint real data, add a route in ./routes — real
 * routes always win over these.
 */
import shapesJson from './catch-all-shapes.json';
import { compileRoutes, matchRoute, type DemoRequest, type DemoRoute, type HttpMethod } from './router';

const shapes = shapesJson as Record<string, unknown>;

const shapeRoutes: DemoRoute[] = Object.entries(shapes).map(([key, value]) => {
  const [method, pattern] = key.split(' ');
  return {
    method: method.toLowerCase() as HttpMethod,
    pattern,
    handler: () => structuredClone(value),
  };
});

const compiled = compileRoutes(shapeRoutes);

/** Mutations should read as successful, not as the "empty" skeleton. */
function polishWrite(value: unknown, method: HttpMethod): unknown {
  if (method === 'get' || !value || typeof value !== 'object' || Array.isArray(value)) return value;
  const v = value as Record<string, unknown>;
  if (v.success === false) v.success = true;
  if (v.message === '') v.message = 'Done (demo)';
  return v;
}

export function catchAll(req: DemoRequest): unknown {
  const hit = matchRoute(compiled, req.method, req.path);
  if (hit) return polishWrite(hit.route.handler({ ...req, params: hit.params }), req.method);

  if (process.env.NODE_ENV !== 'production') {
    // eslint-disable-next-line no-console
    console.debug(`[demo] no mock for ${req.method.toUpperCase()} ${req.path}; returning an empty response`);
  }
  return req.method === 'get' ? {} : { success: true };
}
